while ((mtopi = csr_read(CSR_MTOPI))) {
  mtopi = mtopi >> TOPI_IID_SHIFT;
  switch (mtopi) {
    case IRQ_M_EXT: rc = sbi_irqchip_process(); break;
    default: if (mtopi == sbi_pmu_irq_bit()) { sbi_pmu_ovf_irq(); break; }
  }
}

